sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || !newValue)
        return;

    var user = g_form.getValue('user');

    if (!user)
        return;

    var ga = new GlideAjax('IncentNowClientUtils');
    ga.addParam('sysparm_name', 'validateBusinessUnitHead');
    ga.addParam('sysparm_user_id', user);
    ga.addParam('sysparm_business_unit_id', newValue);

    ga.getXMLAnswer(function(answer) {

        if (!answer)
            return;

        var result;

        try {
            result = JSON.parse(answer);
        } catch (e) {
            return;
        }

        if (!result.valid) {

            // Show message at top of form
            g_form.addErrorMessage(result.message);

            // Show message against Business Unit field
            g_form.showFieldMsg(
                'business_unit',
                result.message,
                'error'
            );

            // Clear invalid BU
            g_form.clearValue('business_unit');
        }
    });
}
